async function value(html, selector, attr) {
  var rows = await triomi.select(html, selector, {v:{selector:'.',attr:attr || 'text'}});
  return rows.length ? rows[0].v || '' : '';
}
async function pageHtml(url) {
  if (!/^https:\/\/www\.manhuagui\.com\//.test(url)) fail('无效的来源地址');
  var r = await triomi.fetch(url, {headers:{Referer:BASE + '/'}});
  if (r.status < 200 || r.status >= 300) fail('HTTP ' + r.status + '，站点可能限制当前网络');
  var h = r.body;
  if (typeof h !== 'string' || !h.trim()) fail('站点返回空页面');
  if (/cf-chl-|challenge-platform|Just a moment|captcha|人机验证|访问过于频繁/i.test(h)) fail('站点要求验证或限制访问，请在浏览器检查');
  if (await value(h, '#__VIEWSTATE, #erroraudit_show', 'outerHtml')) fail('此作品受年龄、地区或登录限制，本规则不解锁受限内容');
  return {html:h,url:r.url || url};
}
function idFrom(url, chapter) {
  var m = (url || '').match(chapter ? /\/comic\/(\d+)\/(\d+)\.html(?:[?#]|$)/ : /\/comic\/(\d+)\/?(?:[?#]|$)/);
  if (!m) fail(chapter ? '章节地址格式无效' : '作品地址格式无效');
  return chapter ? m[1] + '/' + m[2] : m[1];
}
async function list(url, searching) {
  var p = await pageHtml(url), html = p.html;
  var requested = url.match(/_p(\d+)\.html/), actual = p.url.match(/_p(\d+)\.html/);
  if (requested && actual && requested[1] !== actual[1]) {
    if (+requested[1] > 1 && +actual[1] === 1) return [];
    fail('列表跳转到了不同页码');
  }
  var wrapper = searching ? 'div.book-result' : 'ul#contList';
  var rows = await triomi.select(html, wrapper + (searching ? ' > ul > li' : ' > li'), {
    url:{selector:searching ? '.book-detail dl > dt > a' : 'a.bcover',attr:'href',absolute:true},
    title:{selector:searching ? '.book-detail dl > dt > a' : 'a.bcover',attr:'title'},
    text:{selector:searching ? '.book-detail dl > dt > a' : 'p a',attr:'text'},
    cover:{selector:'.bcover img',attr:'src',absolute:true},
    lazy:{selector:'.bcover img',attr:'data-src',absolute:true}
  }, BASE);
  if (!rows.length && !(await value(html, wrapper, 'outerHtml')) &&
      !(searching && /没有找到|未找到|没有搜索|暂无相关|无相关/.test(html))) fail('列表结构不可识别，未返回空成功');
  return rows.map(function(r) {
    if (!r.url || !(r.title || r.text)) fail('列表作品缺少地址或标题');
    return {remoteId:idFrom(r.url),title:r.title || r.text,url:r.url,coverUrl:r.cover || r.lazy || ''};
  });
}
async function discover(url, page) { return list(url, false); }
async function search(keyword, page) {
  if (!String(keyword || '').trim()) return [];
  return list(BASE + '/s/' + encodeURIComponent(keyword) + '_p' + (page || 1) + '.html', true);
}
async function detail(url, item) {
  var id = idFrom(url), p = await pageHtml(BASE + '/comic/' + id + '/'), html = p.html;
  var title = await value(html, '.book-title > h1');
  if (!title) fail('详情缺少作品标题');
  var covers = await triomi.select(html, 'p.hcover > img', {url:{selector:'.',attr:'src',absolute:true}}, BASE);
  var authors = await triomi.select(html, '.detail-list a[href^="/author/"]', {name:{selector:'.'}});
  var meta = {remoteId:id,title:title,url:BASE + '/comic/' + id + '/',
    description:await value(html, '#intro-all'),author:authors.map(function(a){return a.name;}).join(', '),
    coverUrl:covers.length ? covers[0].url : (item && item.coverUrl) || '',
    status:await value(html, '.detail-list li.status > span > span')};
  var sections = await triomi.select(html, 'h4, [id^="chapter-list-"]', {
    id:{selector:'.',attr:'id'},text:{selector:'.'},html:{selector:'.',attr:'outerHtml'}
  });
  var chapters = [], seen = {}, volume = '';
  for (var s = 0; s < sections.length; s++) {
    var section = sections[s];
    if (!section.id) {volume = section.text || ''; continue;}
    var groups = await triomi.select(section.html, 'ul', {html:{selector:'.',attr:'outerHtml'}});
    for (var g = 0; g < groups.length; g++) {
      var rows = await triomi.select(groups[g].html, 'li > a.status0', {
        url:{selector:'.',attr:'href',absolute:true},title:{selector:'.',attr:'title'},text:{selector:'span'}
      }, BASE);
      // Site blocks are oldest-first, with each block internally newest-first.
      rows.reverse();
      for (var c = 0; c < rows.length; c++) {
        var row = rows[c], cid = idFrom(row.url, true);
        if (cid.split('/')[0] !== id) fail('章节不属于当前作品');
        if (seen[cid]) continue;
        seen[cid] = true;
        var name = row.title || (row.text || '').replace(/\s*\d+p\s*$/, '').trim();
        if (!name) fail('章节缺少名称');
        var n = name.match(/\d+(?:\.\d+)?/);
        chapters.push({remoteId:cid,title:name,url:row.url,number:n ? +n[0] : null,volumeTitle:volume});
      }
    }
  }
  if (!chapters.length) fail('没有公开可读章节，作品可能受限或页面结构已变化');
  return {item:meta,chapters:chapters};
}
// Strict quoted-literal reader. Only JavaScript string escapes are interpreted.
