      if (!new RegExp('^[0-9a-fA-F]{' + len + '}$').test(hex)) fail('字符串转义无效');
      out += String.fromCharCode(parseInt(hex, 16)); i += len;
    } else if (c === '\\' || c === "'" || c === '"' || c === '/') out += c;
    else if (c === 'n') out += '\n';
    else if (c === 'r') out += '\r';
    else if (c === 't') out += '\t';
    else if (c === 'b') out += '\b';
    else if (c === 'f') out += '\f';
