async function content(url, chapter, options) {
  var cid = idFrom(url, true), p = await pageHtml(BASE + '/comic/' + cid + '.html');
  var data = unpackData(p.html);
  if (!data || String(data.bid) !== cid.split('/')[0] || String(data.cid) !== cid.split('/')[1]) fail('图片数据与章节身份不符');
